-- Story sessions in Speak:
--   * speak_sessions.kind — 'course' (the build-up method, every existing
--     session) or 'story' (a short tale told in steps);
--   * a third step kind, 'narrate': the narrator reads a passage aloud and
--     there is nothing to answer. It carries its Japanese text and reading
--     like a prompt, so the CHECK that pairs answers with step kinds widens to
--     admit it.
--
-- Generated by drizzle-kit, then made idempotent by hand. Additive: a
-- defaulted column (every existing session becomes 'course') and a CHECK that
-- every existing row already satisfies.

ALTER TABLE "speak_steps" DROP CONSTRAINT IF EXISTS "speak_steps_answer_matches_kind";--> statement-breakpoint
ALTER TABLE "speak_sessions" ADD COLUMN IF NOT EXISTS "kind" text DEFAULT 'course' NOT NULL;--> statement-breakpoint
ALTER TABLE "speak_steps" ADD CONSTRAINT "speak_steps_answer_matches_kind" CHECK (("speak_steps"."kind" in ('prompt', 'narrate') and "speak_steps"."text" is not null and "speak_steps"."reading_kana" is not null)
      or ("speak_steps"."kind" = 'explain' and "speak_steps"."text" is null and "speak_steps"."reading_kana" is null));
